import java.util.*;class Booking{private final Customer customer;private final Show show;private final List<Seat> seats;private boolean cancelled;Booking(Customer c,Show s,List<Seat> x){customer=c;show=s;seats=new ArrayList<>(x);}public double getTotal(){double n=0;for(Seat s:seats)n+=s.getPrice();return n;}public List<Seat> getSeats(){return Collections.unmodifiableList(seats);}public boolean isCancelled(){return cancelled;}void cancel(){if(cancelled)return;for(Seat s:seats)show.release(s);cancelled=true;}}